<?php
require __DIR__.'/includes/bootstrap.php';require_login();require_member($pdo);$memberId=current_member_id();$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$a=$_POST['action']??'';
 if($a==='add_room'||$a==='update_room'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$w=max(.1,(float)str_replace(',','.',$_POST['width_m']??'0'));$l=max(.1,(float)str_replace(',','.',$_POST['length_m']??'0'));if(!$name)throw new RuntimeException('Completează denumirea camerei.');if($a==='add_room'){$pdo->prepare('INSERT INTO house_plan_rooms(name,width_m,length_m,x_pos,y_pos,color,created_by_member_id) VALUES(?,?,?,?,?,?,?)')->execute([$name,$w,$l,0,0,null,$memberId]);$message='Camera a fost adăugată.';}else{$pdo->prepare('UPDATE house_plan_rooms SET name=?,width_m=?,length_m=? WHERE id=?')->execute([$name,$w,$l,$id]);$message='Camera a fost actualizată.';}}
 if($a==='delete_room'){$pdo->prepare('DELETE FROM house_plan_rooms WHERE id=?')->execute([(int)$_POST['id']]);$message='Camera a fost ștearsă.';}
}catch(Throwable $e){$error=$e->getMessage();}}
$rooms=$pdo->query('SELECT * FROM house_plan_rooms ORDER BY id')->fetchAll();$total=0;foreach($rooms as $r)$total+=(float)$r['width_m']*(float)$r['length_m'];
$pageTitle='Planul casei';$active='more';$backUrl='/home.php';require __DIR__.'/includes/layout_top.php';?>
<?php if($message):?><div class="alert success"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?>
<section class="house-plan-summary"><div><span>Suprafață introdusă</span><strong><?=e(number_format($total,1,',','.'))?> m²</strong><small><?=count($rooms)?> <?=count($rooms)===1?'cameră':'camere'?></small></div><button class="btn primary small" data-open-sheet="roomSheet"><?=icon('plus')?> Cameră</button></section>
<section><div class="section-head"><div><h2>Camere</h2><p class="section-copy">Dimensiuni simple, fără hartă interactivă.</p></div></div><div class="room-list"><?php foreach($rooms as $r):$area=(float)$r['width_m']*(float)$r['length_m'];?><article class="room-row"><span class="mini-icon blue"><?=icon('home')?></span><div><strong><?=e($r['name'])?></strong><span><?=e(rtrim(rtrim(number_format((float)$r['width_m'],2,',','.'),'0'),','))?> × <?=e(rtrim(rtrim(number_format((float)$r['length_m'],2,',','.'),'0'),','))?> m · <b><?=e(number_format($area,1,',','.'))?> m²</b></span></div><div class="row-actions"><button class="icon-btn tiny" type="button" data-edit-room data-id="<?=$r['id']?>" data-name="<?=e($r['name'])?>" data-width="<?=e($r['width_m'])?>" data-length="<?=e($r['length_m'])?>"><?=icon('edit')?></button><form method="post" onsubmit="return confirm('Ștergi camera?');"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete_room"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="icon-btn tiny danger"><?=icon('trash')?></button></form></div></article><?php endforeach;?><?php if(!$rooms):?><div class="empty">Adaugă camerele și dimensiunile lor.</div><?php endif;?></div></section>
<div class="modal" id="roomSheet" aria-hidden="true"><div class="modal-backdrop" data-close-sheet></div><section class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><h2>Cameră nouă</h2><button class="icon-btn" data-close-sheet><?=icon('close')?></button></div><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_room"><label>Denumire<input name="name" required placeholder="Living"></label><div class="two-col"><label>Lățime (m)<input name="width_m" inputmode="decimal" placeholder="4,2" required></label><label>Lungime (m)<input name="length_m" inputmode="decimal" placeholder="5,1" required></label></div><button class="btn primary wide">Adaugă camera</button></form></section></div>
<div class="modal" id="roomEditSheet" aria-hidden="true"><div class="modal-backdrop" data-close-sheet></div><section class="sheet"><div class="sheet-handle"></div><div class="sheet-head"><h2>Editează camera</h2><button class="icon-btn" data-close-sheet><?=icon('close')?></button></div><form method="post" class="form-stack" id="roomEditForm"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="update_room"><input type="hidden" name="id"><label>Denumire<input name="name" required></label><div class="two-col"><label>Lățime (m)<input name="width_m" inputmode="decimal" required></label><label>Lungime (m)<input name="length_m" inputmode="decimal" required></label></div><button class="btn primary wide">Salvează</button></form></section></div>
<script>document.querySelectorAll('[data-edit-room]').forEach(b=>b.addEventListener('click',()=>{const f=document.getElementById('roomEditForm'),m=document.getElementById('roomEditSheet');f.elements.id.value=b.dataset.id;f.elements.name.value=b.dataset.name;f.elements.width_m.value=String(b.dataset.width||'').replace('.',',');f.elements.length_m.value=String(b.dataset.length||'').replace('.',',');m.classList.add('open');m.setAttribute('aria-hidden','false');document.body.classList.add('modal-open')}));</script>
<?php require __DIR__.'/includes/layout_bottom.php';?>
